CREATE OR REPLACE PROCEDURE HARNESS_APP.archive_old_orders(
    p_cutoff_date IN DATE
)
AS
    TYPE t_order_rows IS TABLE OF HARNESS_APP.ORDERS%ROWTYPE;
    l_rows t_order_rows;

    CURSOR c_old_orders(p_cutoff IN DATE) IS
        SELECT *
        FROM HARNESS_APP.ORDERS
        WHERE ORDER_DATE < p_cutoff;

    c_batch_size CONSTANT PLS_INTEGER := 10000;
BEGIN
    OPEN c_old_orders(p_cutoff_date);

    LOOP
        FETCH c_old_orders BULK COLLECT INTO l_rows LIMIT c_batch_size;
        EXIT WHEN l_rows.COUNT = 0;

        FORALL i IN 1 .. l_rows.COUNT
            INSERT INTO HARNESS_APP.ORDERS_ARCHIVE (
                ORDER_ID,
                CUSTOMER_ID,
                ORDER_DATE,
                STATUS,
                TOTAL
            )
            VALUES (
                l_rows(i).ORDER_ID,
                l_rows(i).CUSTOMER_ID,
                l_rows(i).ORDER_DATE,
                l_rows(i).STATUS,
                l_rows(i).TOTAL
            );

        FORALL i IN 1 .. l_rows.COUNT
            DELETE FROM HARNESS_APP.ORDERS
            WHERE ORDER_ID = l_rows(i).ORDER_ID;
    END LOOP;

    CLOSE c_old_orders;
END archive_old_orders;
```

