DECLARE
  l_failures          PLS_INTEGER := 0;
  l_department_with   NUMBER;
  l_department_none   NUMBER;
  l_expected          NUMBER;
  l_actual            NUMBER;
  l_count             NUMBER;

  PROCEDURE check_result(
    p_check_name IN VARCHAR2,
    p_expected   IN NUMBER,
    p_actual     IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE('PASS: ' || p_check_name ||
                           ' expected=' || p_expected ||
                           ' actual=' || p_actual);
    ELSE
      DBMS_OUTPUT.PUT_LINE('FAIL: ' || p_check_name ||
                           ' expected=' || p_expected ||
                           ' actual=' || p_actual);
      l_failures := l_failures + 1;
    END IF;
  END check_result;

BEGIN
  SAVEPOINT test_headcount_sp;

  DBMS_OUTPUT.PUT_LINE('Testing HARNESS_APP.headcount');

  -- Find a department_id that has at least one employee.
  BEGIN
    SELECT MIN(department_id)
      INTO l_department_with
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN OTHERS THEN
      l_department_with := NULL;
  END;

  IF l_department_with IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: setup found no non-NULL department_id in employees to test a matching key');
    l_failures := l_failures + 1;
  ELSE
    -- Expected value computed independently from the same predicate used by headcount.
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_department_with;

    l_actual := HARNESS_APP.headcount(l_department_with);

    check_result(
      p_check_name => 'matching non-NULL department_id',
      p_expected   => l_expected,
      p_actual     => l_actual
    );
  END IF;

  -- Find a non-NULL department_id that matches no employee.
  -- Start with a likely unused negative value, then confirm it really matches no row.
  BEGIN
    SELECT COUNT(*)
      INTO l_count
      FROM employees
     WHERE department_id = -1;

    IF l_count = 0 THEN
      l_department_none := -1;
    ELSE
      -- If -1 exists, try one value above the maximum non-NULL department_id.
      SELECT MAX(department_id) + 1
        INTO l_department_none
        FROM employees
       WHERE department_id IS NOT NULL;

      SELECT COUNT(*)
        INTO l_count
        FROM employees
       WHERE department_id = l_department_none;

      IF l_count <> 0 THEN
        l_department_none := NULL;
      END IF;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      l_department_none := NULL;
  END;

  IF l_department_none IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: setup found no non-NULL department_id that matches no row in employees');
    l_failures := l_failures + 1;
  ELSE
    -- Expected value for a non-matching key is 0.
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_department_none;

    l_actual := HARNESS_APP.headcount(l_department_none);

    check_result(
      p_check_name => 'non-matching non-NULL department_id',
      p_expected   => l_expected,
      p_actual     => l_actual
    );
  END IF;

  -- NULL argument case.
  -- The function uses WHERE department_id = p_department_id.
  -- For a NULL argument, that comparison matches no rows, so the expected result is 0.
  l_expected := 0;
  l_actual   := HARNESS_APP.headcount(NULL);

  check_result(
    p_check_name => 'NULL department_id argument',
    p_expected   => l_expected,
    p_actual     => l_actual
  );

  ROLLBACK TO test_headcount_sp;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(-20999, 'headcount test block failed: ' || l_failures || ' check(s) failed');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: unexpected error in headcount test block: ' || SQLERRM);
    ROLLBACK TO test_headcount_sp;
    RAISE;
END;
```

The block checks three cases:

1. A non-NULL `department_id` that has at least one row in `employees`. The expected count is computed independently with the same predicate used by `headcount`, then compared with the function result. If no such department exists, the setup check prints `FAIL` and counts as a failure.

2. A non-NULL `department_id` that matches no row. The block first tries `-1` and confirms it matches no row; if that value is present, it tries one value above the maximum non-NULL `department_id` and confirms that too. If no such value can be found, the setup check prints `FAIL` and counts as a failure.

3. A `NULL` argument. Because the function compares with `department_id = p_department_id`, a `NULL` argument matches no rows, so the expected result is `0`.

The block uses a savepoint, rolls back to it at the end, and in the exception section rolls back to it and re-raises. I have not run this block.

